// O(n log n) patience sorting - gives LIS length
function lisLength(arr) {
  const tails = []; // tails[i] = smallest tail of all IS of length i+1

  for (const x of arr) {
    // binary search: find leftmost pos where tails[pos] >= x
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1; // strictly increasing: use <
      else hi = mid;
    }
    tails[lo] = x; // replace or append
  }

  return tails.length;
}

// O(n²) DP - gives actual subsequence via parent tracking
function lisActual(arr) {
  const n = arr.length;
  const dp = new Array(n).fill(1);
  const parent = new Array(n).fill(-1);

  let maxLen = 1, maxIdx = 0;
  for (let i = 1; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[j] < arr[i] && dp[j] + 1 > dp[i]) {
        dp[i] = dp[j] + 1;
        parent[i] = j;
      }
    }
    if (dp[i] > maxLen) { maxLen = dp[i]; maxIdx = i; }
  }

  // reconstruct subsequence by following parent pointers
  const result = [];
  for (let i = maxIdx; i !== -1; i = parent[i]) result.push(arr[i]);
  return result.reverse();
}
